import React, { useEffect, useState, useCallback } from "react";
import axios from "axios";
import { FaBook, FaChartLine, FaTasks, FaCheckCircle } from "react-icons/fa";
import AlertBox from "./AlertBox";
import ProgressChart from "./ProgressChart";
import DashboardCard from "./DashboardCard";
import PageHeader from "./PageHeader";
import "./dashboard.css";

function StudentDashboard() {
  const userId = localStorage.getItem("user_id");
  const userName = localStorage.getItem("user_name");

  const [courses, setCourses] = useState([]);
  const [progress, setProgress] = useState({});
  const [alert, setAlert] = useState(null);

  const fetchCourses = useCallback(async () => {
    try {
      const res = await axios.get("http://127.0.0.1:8000/courses");
      const allCourses = res.data.courses || [];

      const enrollRes = await axios.get(
        `http://127.0.0.1:8000/enrollments/${userId}`
      );
      const enrolledIds = enrollRes.data.map((e) => e.course_id);

      const myCourses = allCourses.filter((c) => enrolledIds.includes(c.id));
      setCourses(myCourses);

      const progressRes = await axios.get(
        `http://127.0.0.1:8000/progress/${userId}`
      );

      const progressMap = {};
      (progressRes.data.progress || []).forEach((item) => {
        progressMap[item.course_id] = {
          completed_topics: item.completed_topics,
          total_topics: item.total_topics,
          status: item.status
        };
      });

      setProgress(progressMap);
    } catch (err) {
      console.error(err);
    }
  }, [userId]);

  useEffect(() => {
    fetchCourses();
  }, [fetchCourses]);

  const handleProgress = async (courseId, value) => {
    try {
      const response = await axios.post(
        "http://127.0.0.1:8000/update-progress",
        {
          user_id: parseInt(userId),
          course_id: courseId,
          completed_topics: parseInt(value)
        }
      );

      setAlert({
        message: response.data.message,
        type: "success"
      });

      fetchCourses();
      window.dispatchEvent(new Event("plannerUpdated"));
    } catch (err) {
      console.error(err);
      setAlert({
        message: "Failed to update progress",
        type: "error"
      });
    }
  };

  const completedCount = Object.values(progress).filter(
    (p) => p.status === "Completed"
  ).length;

  const averageProgress =
    courses.length > 0
      ? Math.round(
          courses.reduce((acc, course) => {
            const courseProgress = progress[course.id] || {
              completed_topics: 0,
              total_topics: 10
            };
            return (
              acc +
              (courseProgress.completed_topics / courseProgress.total_topics) * 100
            );
          }, 0) / courses.length
        )
      : 0;

  const chartData = courses.map((course) => {
    const courseProgress = progress[course.id] || {
      completed_topics: 0,
      total_topics: 10
    };

    const percentage = Math.round(
      (courseProgress.completed_topics / courseProgress.total_topics) * 100
    );

    return {
      course: course.title,
      progress: percentage
    };
  });

  return (
    <div>
      {alert && (
        <AlertBox
          message={alert.message}
          type={alert.type}
          onClose={() => setAlert(null)}
        />
      )}

      <PageHeader
        title={`Student Dashboard`}
        subtitle={`Track your enrolled courses, progress, and learning analytics, ${userName || "Student"}.`}
      />

      <div className="grid-4" style={{ marginBottom: "18px" }}>
        <DashboardCard
          icon={<FaBook />}
          label="Enrolled Courses"
          value={courses.length}
        />
        <DashboardCard
          icon={<FaCheckCircle />}
          label="Completed Courses"
          value={completedCount}
        />
        <DashboardCard
          icon={<FaChartLine />}
          label="Average Progress"
          value={`${averageProgress}%`}
        />
        <DashboardCard
          icon={<FaTasks />}
          label="Learning Status"
          value="Active"
          badge="Live"
        />
      </div>

      <div className="section-card" style={{ marginBottom: "18px" }}>
        <h4>My Enrolled Courses</h4>

        {courses.length === 0 ? (
          <p>No enrolled courses found.</p>
        ) : (
          <div className="grid-3">
            {courses.map((course) => {
              const courseProgress = progress[course.id] || {
                completed_topics: 0,
                total_topics: 10,
                status: "In Progress"
              };

              const percentage = Math.round(
                (courseProgress.completed_topics / courseProgress.total_topics) * 100
              );

              return (
                <div className="list-card" key={course.id}>
                  <h4 style={{ marginTop: 0, marginBottom: "8px" }}>
                    {course.title}
                  </h4>

                  <div className="meta">{course.description}</div>
                  <div className="meta">Subject Code: {course.subject_code}</div>
                  <div className="meta">Created By: {course.created_by || "Unknown"}</div>

                  <div
                    style={{
                      height: "10px",
                      background: "#e5e7eb",
                      borderRadius: "999px",
                      overflow: "hidden",
                      marginTop: "12px"
                    }}
                  >
                    <div
                      style={{
                        width: `${percentage}%`,
                        height: "100%",
                        background: "linear-gradient(135deg, #6d28d9, #8b5cf6)"
                      }}
                    />
                  </div>

                  <div className="meta" style={{ marginTop: "10px" }}>
                    Progress: {percentage}%
                  </div>

                  <div style={{ marginTop: "8px" }}>
                    <span
                      className={
                        courseProgress.status === "Completed"
                          ? "badge badge-green"
                          : "badge badge-orange"
                      }
                    >
                      {courseProgress.status}
                    </span>
                  </div>

                  <input
                    className="input"
                    type="number"
                    min="0"
                    max={courseProgress.total_topics}
                    placeholder={`Completed topics (0-${courseProgress.total_topics})`}
                    id={`progress-${course.id}`}
                    style={{ marginTop: "12px" }}
                  />

                  <button
                    className="btn btn-primary"
                    onClick={() => {
                      const value = document.getElementById(`progress-${course.id}`).value;
                      handleProgress(course.id, value || 0);
                    }}
                  >
                    Update Progress
                  </button>
                </div>
              );
            })}
          </div>
        )}
      </div>

      <ProgressChart data={chartData} />
    </div>
  );
}

export default StudentDashboard;
